Theorem b2jv_callee_L1 : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH (ce ML).
Proof.
  destruct TOP_L as (s & Hgp & Hho & CERT).
  refine (contract_of_cert_rec_cut_all PSEGS IT APLAIN plain_in_hull plain_hull_ok IT_ok [] GPLAIN fx_ok RZ RZ_step RZ_msteps RZ_exit RZ_conseq AINVH
            AINVH_frame AINVH_zone AINVH_disj plain_G_ro_img plain_G_img_ceil
            (ce ML) 14 idepth_lt (RUN_sound_fx PSEGS) LIMIT 0%nat BFUEL FUEL (XN ML) _ (top ML) s Hgp Hho (XB ML) _ (CUTS ML) _ CERT).
  - intros n PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV Hn HB0 HC0 HBc HCc HUa HUm CC. unfold XN.
    apply (XNr_sound PSEGS IT APLAIN plain_in_hull plain_hull_ok IT_ok [] GPLAIN fx_ok RZ RZ_step AINVH AINVH_frame AINVH_zone AINVH_disj AINVH_perm
             plain_G_ro_img plain_G_img_ceil plain_G_img_hull nil_SWIN_img plain_SEGS_out NXF BCAP CCAP PERMf TOPf FS0 FDS0 HID M0 B0 C0 HB0 HC0 HBc HCc UINV HUa
             213%nat 14%nat ceL1 CT0 CT0_sound n).
    + (apply GC_all; first [assumption | exact IT_ok]).
    + exact CC.
    + exact HUm.
  - intros n PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV Hn HB0 HC0 HBc HCc HUa HUm CC. unfold XB.
    apply (XBc_sound PSEGS APLAIN plain_in_hull plain_hull_ok NXF [] GPLAIN BCAP CCAP fx_ok RZ RZ_step AINVH AINVH_zone AINVH_disj AINVH_perm
             plain_G_ro_img plain_G_img_ceil plain_G_img_hull nil_SWIN_img plain_SEGS_out PERMf TOPf FS0 FDS0 HID M0 B0 C0 HB0 HC0 HBc HCc UINV HUa CT2 CT2_sound).
    (apply OBL2_all; assumption).
  - exact (cuts_ok_of ML CERTS_L).
Qed.

