Lemma CTs_sound : forall id c, CTs id = Some c -> callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH c.
Proof.
  intros id c H. unfold CTs in H. destruct (Nat.eqb id 213).
  - injection H as <-. exact b2jv_callee_L1.
  - exact (CT0_sound _ _ H).
Qed.
Theorem b2jv_callee_S : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH (ce MS).
Proof.
  destruct TOP_S as (s & Hgp & Hho & CERT).
