    apply (XNc_sound PSEGS IT APLAIN plain_in_hull plain_hull_ok IT_ok NXF [] GPLAIN BCAP CCAP fx_ok RZ RZ_step AINVH AINVH_frame AINVH_zone AINVH_disj AINVH_perm
