Section Contract.
Context {RC : run_ceil}.
Variable RZ : GPS.rz_t.
Hypothesis RZ_step : GPS.RZ_STEP PSEGS RZ.
Hypothesis RZ_msteps : GPS.RZ_MSTEPS PSEGS RZ.
Hypothesis RZ_exit : GPS.RZ_EXIT PSEGS RZ.
Hypothesis RZ_conseq : GPS.RZ_CONSEQ RZ.
Variable AINVH : list (Z * Z) -> Z -> Z -> (word -> option byte) -> Model -> Prop.
Hypothesis AINVH_frame : forall L B C M M' mdl,
  AINVH L B C M mdl ->
  (forall a, M' a <> M a -> (in_blocks L (bv_unsigned a) \/ CEIL_run <= bv_unsigned a \/ in_wins [] (bv_unsigned a)) /\ M' a <> None) ->
  AINVH L B C M' mdl.
Hypothesis AINVH_zone : forall L B C M mdl b m, AINVH L B C M mdl -> In (b, m) L -> blk_ok GPLAIN b m.
Hypothesis AINVH_disj : forall L B C M mdl L1 L2 b m b' m',
  AINVH L B C M mdl -> L = L1 ++ (b, m) :: L2 -> In (b', m') (L1 ++ L2) -> b + m <= b' \/ b' + m' <= b.
Hypothesis AINVH_perm : forall L L' B C M mdl, Permutation.Permutation L L' -> AINVH L B C M mdl -> AINVH L' B C M mdl.
Hypothesis GC_all : forall IT NXF bc cc PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV,
  AX2.itab_sound PSEGS IT -> 0 <= B0 -> 0 <= C0 -> B0 + bc <= GBUDGET -> C0 + cc <= GCOUNT -> (forall E E', env_agree NXF E E' -> UINV E -> UINV E') ->
  gcontracts PSEGS IT APLAIN NXF PERMf TOPf FS0 FDS0 (AINV_f [] GPLAIN AINVH PERMf TOPf HID M0 B0 C0) fx_ok UINV RZ GPLAIN bc cc.
Hypothesis OBL2_all : forall NXF bc cc PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV,
  0 <= B0 -> 0 <= C0 -> B0 + bc <= GBUDGET -> C0 + cc <= GCOUNT -> (forall E E', env_agree NXF E E' -> UINV E -> UINV E') ->
  OBL_str_resize2 PSEGS NXF PERMf TOPf FS0 FDS0 (AINV_f [] GPLAIN AINVH PERMf TOPf HID M0 B0 C0) fx_ok UINV RZ GPLAIN bc cc.
(* [comment removed for export] *)
Hypothesis VEC_CTOR : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH VecCtor.ce.            (* [comment removed for export] *)
Hypothesis VEC_PUSH_FULL : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH (VecPush.ce true).  (* [comment removed for export] *)
Hypothesis VEC_PUSH_EMPTY : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH (VecPush.ce false). (* [comment removed for export] *)
Hypothesis B2J : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH (c2_merged B2Jn.ce2).          (* [comment removed for export] *)
Hypothesis STR_CTOR : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH GpStrCtor.ce.          (* [comment removed for export] *)
Hypothesis READ : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH (c2_merged GpRead.ce2).      (* [comment removed for export] *)

Lemma CT_N_sound : forall id c, FuzzNP.CT id = Some c -> callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH c.
Proof.
  intros id c H. unfold FuzzNP.CT in H.
  destruct (Nat.eqb id 110); [injection H as <-; exact VEC_CTOR|].
  destruct (Nat.eqb id 111); [injection H as <-; exact STR_CTOR|].
  destruct (Nat.eqb id 114); [injection H as <-; exact VEC_PUSH_FULL|]. discriminate H.
Qed.
Lemma CT2_sound : forall id c, FuzzNP.CT2 id = Some c -> callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH (c2_merged c).
Proof.
  intros id c H. unfold FuzzNP.CT2 in H.
  destruct (Nat.eqb id 112); [injection H as <-; exact READ|].
  destruct (Nat.eqb id 113); [injection H as <-; exact B2J|]. discriminate H.
Qed.
Lemma CT_E_sound : forall id c, FuzzEP.CT id = Some c -> callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH c.
Proof.
  intros id c H. unfold FuzzEP.CT in H.
  destruct (Nat.eqb id 111); [injection H as <-; exact STR_CTOR|].
  destruct (Nat.eqb id 115); [injection H as <-; exact VEC_PUSH_EMPTY|]. discriminate H.
Qed.

Theorem fuzz_callee_N : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH FuzzN.ce.
Proof.
  refine (contract_of_cert_xb PSEGS APLAIN plain_in_hull plain_hull_ok [] GPLAIN fx_ok RZ RZ_step RZ_msteps RZ_exit RZ_conseq (RUN_sound_fx PSEGS)
            AINVH AINVH_frame AINVH_zone AINVH_disj plain_G_ro_img plain_G_img_ceil
            FuzzN.ce FuzzNP.IT FuzzNP.IT_ok FuzzNP.LIMIT 0%nat FuzzNP.BFUEL FuzzNP.FUEL FuzzNP.XN _ FuzzNP.XB _ FuzzNP.planN _
            FuzzNP.gplan FuzzNP.hshape GpFuzzNcert.cert).
  - intros PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV HB0 HC0 HBc HCc HUa. unfold FuzzNP.XN.
    apply (XNc_sound PSEGS FuzzNP.IT APLAIN plain_in_hull plain_hull_ok FuzzNP.IT_ok FuzzN.NXF [] GPLAIN FuzzN.BCAP FuzzN.CCAP fx_ok RZ RZ_step
              AINVH AINVH_frame AINVH_zone AINVH_disj AINVH_perm
              plain_G_ro_img plain_G_img_ceil plain_G_img_hull nil_SWIN_img plain_SEGS_out PERMf TOPf FS0 FDS0 HID M0 B0 C0 HB0 HC0 HBc HCc UINV HUa FuzzNP.CT).
    + exact CT_N_sound.
    + (apply GC_all; first [assumption | exact FuzzNP.IT_ok]).
  - intros PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV HB0 HC0 HBc HCc HUa. unfold FuzzNP.XB.
    apply (XBc_sound PSEGS APLAIN plain_in_hull plain_hull_ok FuzzN.NXF [] GPLAIN FuzzN.BCAP FuzzN.CCAP fx_ok RZ RZ_step AINVH AINVH_zone AINVH_disj AINVH_perm
              plain_G_ro_img plain_G_img_ceil plain_G_img_hull nil_SWIN_img plain_SEGS_out PERMf TOPf FS0 FDS0 HID M0 B0 C0 HB0 HC0 HBc HCc UINV HUa FuzzNP.CT2).
    + exact CT2_sound.
    + (apply OBL2_all; assumption).
Qed.

Theorem fuzz_callee_E : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH FuzzE.ce.
Proof.
  refine (contract_of_cert_xb PSEGS APLAIN plain_in_hull plain_hull_ok [] GPLAIN fx_ok RZ RZ_step RZ_msteps RZ_exit RZ_conseq (RUN_sound_fx PSEGS)
            AINVH AINVH_frame AINVH_zone AINVH_disj plain_G_ro_img plain_G_img_ceil
            FuzzE.ce FuzzEP.IT FuzzEP.IT_ok FuzzNP.LIMIT 0%nat FuzzNP.BFUEL FuzzNP.FUEL FuzzEP.XN _ FuzzEP.XB _ FuzzEP.planE _
            FuzzEP.gplan FuzzEP.hshape GpFuzzEcert.cert).
  - intros PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV HB0 HC0 HBc HCc HUa. unfold FuzzEP.XN.
    apply (XNc_sound PSEGS FuzzEP.IT APLAIN plain_in_hull plain_hull_ok FuzzEP.IT_ok FuzzN.NXF [] GPLAIN FuzzE.BCAP FuzzE.CCAP fx_ok RZ RZ_step
              AINVH AINVH_frame AINVH_zone AINVH_disj AINVH_perm
              plain_G_ro_img plain_G_img_ceil plain_G_img_hull nil_SWIN_img plain_SEGS_out PERMf TOPf FS0 FDS0 HID M0 B0 C0 HB0 HC0 HBc HCc UINV HUa FuzzEP.CT).
    + exact CT_E_sound.
    + (apply GC_all; first [assumption | exact FuzzEP.IT_ok]).
  - intros PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV HB0 HC0 HBc HCc HUa. unfold FuzzEP.XB.
    apply (XBc_sound PSEGS APLAIN plain_in_hull plain_hull_ok FuzzN.NXF [] GPLAIN FuzzE.BCAP FuzzE.CCAP fx_ok RZ RZ_step AINVH AINVH_zone AINVH_disj AINVH_perm
              plain_G_ro_img plain_G_img_ceil plain_G_img_hull nil_SWIN_img plain_SEGS_out PERMf TOPf FS0 FDS0 HID M0 B0 C0 HB0 HC0 HBc HCc UINV HUa FuzzNP.CT2).
    + exact CT2_sound.
    + (apply OBL2_all; assumption).
Qed.
End Contract.
End GpFuzzC.
