Lemma read_cert :
  check PSEGS IT APLAIN NXF LIMIT XN (B2JCutShare.GlzCallCert.XE0) XB XC0 (HSce ce) 0%nat 600%nat 3000%nat None tin plan_read = COk (SHole 0).
Proof. vm_compute. reflexivity. Qed.
Lemma read_gplan : gplan_ok plan_read = true. Proof. vm_compute. reflexivity. Qed.
