Lemma CT2_sound : forall id c, CT2 id = Some c -> callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH (c2_merged c).
Proof.
  intros id c H. unfold CT2 in H. destruct (Nat.eqb id 101); [|discriminate H]. injection H as <-.
  exact (fms_callee RZ RZ_step RZ_msteps RZ_exit RZ_conseq AINVH AINVH_frame AINVH_zone AINVH_disj AINVH_perm GC_all OBL2_all).
Qed.

Theorem read_callee : callee_contract PSEGS [] GPLAIN fx_ok RZ AINVH ce.
Proof.
  refine (contract_of_cert_xb PSEGS APLAIN plain_in_hull plain_hull_ok [] GPLAIN fx_ok RZ RZ_step RZ_msteps RZ_exit RZ_conseq (RUN_sound_fx PSEGS)
            AINVH AINVH_frame AINVH_zone AINVH_disj plain_G_ro_img plain_G_img_ceil
            ce IT IT_ok LIMIT 0%nat 600%nat 3000%nat XN _ XB _ plan_read _ read_gplan read_shape read_cert).
  - intros PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV HB0 HC0 HBc HCc HUa. unfold XN.
    apply (XNc_sound PSEGS IT APLAIN plain_in_hull plain_hull_ok IT_ok NXF [] GPLAIN BCAP CCAP fx_ok RZ RZ_step AINVH AINVH_frame AINVH_zone AINVH_disj AINVH_perm
              plain_G_ro_img plain_G_img_ceil plain_G_img_hull nil_SWIN_img plain_SEGS_out PERMf TOPf FS0 FDS0 HID M0 B0 C0 HB0 HC0 HBc HCc UINV HUa CT).
    + intros id ce' H. discriminate H.
    + (apply GC_all; first [assumption | exact IT_ok]).
  - intros PERMf TOPf HID M0 B0 C0 FS0 FDS0 UINV HB0 HC0 HBc HCc HUa. unfold XB.
    apply (XBc_sound PSEGS APLAIN plain_in_hull plain_hull_ok NXF [] GPLAIN BCAP CCAP fx_ok RZ RZ_step AINVH AINVH_zone AINVH_disj AINVH_perm
              plain_G_ro_img plain_G_img_ceil plain_G_img_hull nil_SWIN_img plain_SEGS_out PERMf TOPf FS0 FDS0 HID M0 B0 C0 HB0 HC0 HBc HCc UINV HUa CT2).
    + exact CT2_sound.
    + (apply OBL2_all; assumption).
Qed.
